export interface Quote {
  text: string;
  source: string;
  author: string;
}

export interface Level {
  name: string;
  minXP: number;
}

export interface GameState {
  xp: number;
  completedQuotes: number;
}

export interface Settings {
  ghostEnabled: boolean;
  readAheadEnabled: boolean;
}

export enum GameStatus {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  COMPLETED = 'COMPLETED', // Successfully typed with 100% accuracy
  FAILED = 'FAILED', // Typed but mistakes were present at the end
}

import React, { useState, useEffect, useCallback } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import { Quote, Settings } from './types';
import { fetchQuotes } from './services/geminiService';
import { Loader2, Settings as SettingsIcon, Flame } from 'lucide-react';

const App: React.FC = () => {
  const [xp, setXp] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_xp');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    return saved ? JSON.parse(saved) : { ghostEnabled: false, readAheadEnabled: false };
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);
  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Persistence
  useEffect(() => { localStorage.setItem('frogType_xp', xp.toString()); }, [xp]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);

  const loadMoreQuotes = useCallback(async () => {
    try {
      const newQuotes = await fetchQuotes(5);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    }
  }, []);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await loadMoreQuotes();
      setLoading(false);
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Set current quote if null and queue has items
  useEffect(() => {
    if (!currentQuote && quotesQueue.length > 0) {
      const next = quotesQueue[0];
      setCurrentQuote(next);
      setQuotesQueue(prev => prev.slice(1));
    }

    // Low buffer warning
    if (quotesQueue.length < 3 && quotesQueue.length > 0) {
      loadMoreQuotes();
    }
  }, [currentQuote, quotesQueue, loadMoreQuotes]);

  const handleQuoteComplete = (earnedXp: number, wpm: number) => {
    setXp(prev => prev + earnedXp);
    setStreak(prev => prev + 1);
    setLastWpm(wpm);
    setCurrentQuote(null); // Triggers effect to pop next quote
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);

  return (
    <div className="min-h-screen flex flex-col bg-[#f7f7f5] text-stone-800 font-sans selection:bg-frog-200">
      {/* Top Bar Navigation */}
      <header className="w-full bg-white/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-8 py-5 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-6 md:gap-12">

          {/* Logo Area - Top Left */}
          <div className="flex flex-col items-center md:items-start flex-shrink-0">
             <h1 className="text-2xl font-black text-frog-800 tracking-tight flex items-center gap-2">
               <span className="text-3xl">🐸</span> Frog Type
             </h1>
             <p className="text-stone-400 text-xs font-medium ml-1">Cozy Typing Progression</p>
          </div>

          {/* Progress Bar Area - Right/Center */}
          <div className="w-full md:flex-grow md:max-w-3xl flex items-center gap-4">
             <ProgressBar xp={xp} />
             {/* Streak Badge in Header */}
             <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full font-mono text-xs font-bold transition-all ${streak > 0 ? 'bg-orange-50 text-orange-500' : 'bg-stone-100 text-stone-400'}`}>
                <Flame className={`w-3.5 h-3.5 ${streak > 0 ? 'fill-orange-500 animate-pulse' : ''}`} />
                <span>{streak}</span>
             </div>
             <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors">
                <SettingsIcon className="w-5 h-5" />
             </button>
          </div>

        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full max-w-4xl flex items-center justify-center min-h-[50vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Hatching quotes...</p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onRequestNewQuote={() => setCurrentQuote(null)}
              streak={streak}
              ghostWpm={lastWpm}
              settings={settings}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Quote, GameStatus, Settings } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number) => void;
  onFail: () => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings 
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED) {
        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status]);

  const handleFocus = () => {
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        // Update WPM
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        // Update Ghost
        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            // Ghost speed: chars = WPM * 5 * mins
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50); // 20fps update for smooth ghost
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;

    // Start timer on first char
    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    setInput(val);

    // Check completion
    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const handleRetry = () => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleNext = () => {
    onComplete(calculateXP(wpm, quote.text.length), wpm);
  };

  // Helper for Read Ahead logic
  const getReadAheadState = (index: number) => {
    if (!settings.readAheadEnabled) return { isHidden: false, isHighlighted: false };

    // Find current word boundaries
    // "Current Word" is the one the caret is currently in or just finished
    const text = quote.text;
    const caret = input.length;

    // Find start of current word (go back from caret until space)
    let start = text.lastIndexOf(' ', caret - 1);
    start = start === -1 ? 0 : start + 1;

    // Find end of current word (go forward from caret until space)
    let end = text.indexOf(' ', caret);
    if (end === -1) end = text.length;

    // Check if index is in current word
    if (index >= start && index < end) {
        return { isHidden: true, isHighlighted: false };
    }

    // Check if index is in next word
    // Next word starts after `end` space
    if (index > end) { // Strict greater to skip the space itself
        let nextEnd = text.indexOf(' ', end + 1);
        if (nextEnd === -1) nextEnd = text.length;
        if (index < nextEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Untyped
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      // Status Coloring
      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800'; // Correct
        } else {
          colorClass = 'text-red-500 bg-red-100'; // Incorrect
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-600 font-bold';
              bgClass = 'bg-frog-50';
          }
      }

      // Read Ahead Visibility
      // We only hide Untyped or Correctly typed characters of the current word
      // If error, we still show it (handled by colorClass override above?)
      // Actually if opacity is 0, nothing shows.
      // We want to hide the "Prompt" text for the current word.
      // But we show what the user typed? 
      // The prompt says "hides the word user is typing to he has to remember it".
      // This implies the *model* text is hidden.
      // If user types, we normally color the model text.
      // Let's set opacity to 0 but keep cursor/errors visible?
      // If I set `opacity-0`, the user sees nothing.
      // Let's use `text-transparent` but keep background?

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} className="relative inline-block">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}
            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char === ' ' && isHidden ? ' ' : char}
                {/* Ensure space has width even if transparent */}
            </span>
        </span>
      );
    });
  };

  return (
    <div 
      className="relative w-full max-w-3xl mx-auto min-h-[280px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-white/60 backdrop-blur-[2px] cursor-pointer rounded-3xl border-2 border-dashed border-frog-200/50 hover:border-frog-300 transition-all"
        >
          <div className="text-center animate-bounce text-frog-500">
            <Play className="w-8 h-8 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-sm tracking-wide uppercase">Click or Type to Start</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-8 md:p-12 bg-white rounded-3xl transition-all duration-300
        ${!isFocused ? 'blur-[1px] opacity-50' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-100 shadow-[0_0_20px_rgba(239,68,68,0.15)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-100 bg-frog-50/30' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : 'shadow-[0_8px_30px_rgb(0,0,0,0.04)]'}
      `}>

        {/* Source Header */}
        <div className="absolute top-6 left-8 right-8 flex justify-between text-[10px] font-bold text-stone-300 uppercase tracking-widest select-none">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3 h-3"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadEnabled && <span className="text-frog-300 flex items-center gap-1"><EyeOff className="w-3 h-3"/> Read Ahead</span>}
          </div>
          <span>{quote.author}</span>
        </div>

        {/* Text Display */}
        <div 
          className="font-mono text-2xl md:text-3xl leading-relaxed break-words mb-10 mt-4 relative z-10 outline-none select-none"
          onClick={handleFocus}
        >
          {renderText()}
        </div>

        {/* Hidden Input */}
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => setIsFocused(true)}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        {/* Status Bar */}
        <div className="absolute bottom-6 left-8 right-8 flex justify-between items-end select-none">
           <div className="flex items-center gap-6 text-stone-400 font-mono text-xs">
             <div className="flex flex-col">
                <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5">Speed</span>
                <span className="font-bold text-base text-stone-600">{wpm} <span className="text-[10px] font-normal">WPM</span></span>
             </div>
             {status === GameStatus.COMPLETED && (
                 <div className="flex flex-col animate-pulse text-frog-600">
                    <span className="text-[9px] uppercase font-bold text-frog-400 mb-0.5">XP Earned</span>
                    <span className="font-bold text-base">+{calculateXP(wpm, quote.text.length)}</span>
                 </div>
             )}
             {/* Streak Indicator in-game */}
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5">Streak</span>
                    <span className="font-bold text-base flex items-center gap-1">
                        <Flame className={`w-3 h-3 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-4 py-1.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-xs tracking-wide"
                >
                  <RotateCcw className="w-3 h-3" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-5 py-2 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200/50 font-bold text-xs tracking-wide"
                >
                  Next Quote <Award className="w-3 h-3" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-4 h-4 text-stone-300 text-[10px] transition-opacity duration-500">
        {status === GameStatus.FAILED ? <span className="text-red-300">100% Accuracy Required. Streak Reset.</span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-400">Perfect! Streak +1</span> :
         isFocused ? "Type the quote above exactly." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React from 'react';
import { Settings } from '../types';
import { X, Ghost, EyeOff, Zap } from 'lucide-react';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: Settings;
  setSettings: (s: Settings) => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, settings, setSettings }) => {
  if (!isOpen) return null;

  const toggleGhost = () => setSettings({ ...settings, ghostEnabled: !settings.ghostEnabled });
  const toggleReadAhead = () => setSettings({ ...settings, readAheadEnabled: !settings.readAheadEnabled });

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-stone-900/20 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm overflow-hidden">
        <div className="flex justify-between items-center p-4 border-b border-stone-100">
          <h2 className="text-lg font-bold text-stone-700 flex items-center gap-2">
            Settings
          </h2>
          <button onClick={onClose} className="text-stone-400 hover:text-stone-600">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-4 space-y-4">

          {/* Ghost Mode Toggle */}
          <div 
            onClick={toggleGhost}
            className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${settings.ghostEnabled ? 'bg-purple-50 border-purple-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.ghostEnabled ? 'bg-purple-100 text-purple-600' : 'bg-stone-200 text-stone-500'}`}>
                <Ghost className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Ghost Replay</div>
                <div className="text-[10px] text-stone-400">Race against your previous speed</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.ghostEnabled ? 'bg-purple-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.ghostEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </div>

          {/* Read Ahead Toggle */}
          <div 
             onClick={toggleReadAhead}
             className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${settings.readAheadEnabled ? 'bg-frog-50 border-frog-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.readAheadEnabled ? 'bg-frog-100 text-frog-600' : 'bg-stone-200 text-stone-500'}`}>
                <EyeOff className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Read Ahead Mode</div>
                <div className="text-[10px] text-stone-400">Hide current word to force focus</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.readAheadEnabled ? 'bg-frog-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.readAheadEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </div>

        </div>

        <div className="p-4 bg-stone-50 text-center">
            <button onClick={onClose} className="text-xs font-bold text-stone-500 hover:text-stone-700">Close</button>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

export interface Quote {
  text: string;
  source: string;
  author: string;
}

export interface Level {
  name: string;
  minXP: number;
}

export interface GameState {
  xp: number;
  completedQuotes: number;
}

export type MusicSource = 'NONE' | 'YOUTUBE' | 'SPOTIFY';

export interface MusicConfig {
  source: MusicSource;
  presetId: string;
}

export interface Settings {
  ghostEnabled: boolean;
  readAheadEnabled: boolean;
  musicConfig: MusicConfig;
}

export enum GameStatus {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  COMPLETED = 'COMPLETED', // Successfully typed with 100% accuracy
  FAILED = 'FAILED', // Typed but mistakes were present at the end
}

import { GoogleGenAI, Type } from "@google/genai";
import { Quote } from '../types';

// --- QUOTES DATABASE (FALLBACK) ---
// This array acts as the local "database" when the API is unavailable.
// Modify this list to add or change hardcoded quotes.
const FALLBACK_QUOTES: Quote[] = [
  {
    text: "The unexamined life is not worth living.",
    source: "Philosophy",
    author: "Socrates"
  },
  {
    text: "For God has not given us a spirit of fear, but of power and of love and of a sound mind.",
    source: "Bible",
    author: "2 Timothy 1:7"
  },
  {
    text: "We did not send down the Quran to you to cause you any hardship.",
    source: "Quran",
    author: "Rashad Khalifa Translation (20:2)"
  },
  {
    text: "I think, therefore I am.",
    source: "Philosophy",
    author: "René Descartes"
  },
  {
    text: "Love is patient, love is kind. It does not envy, it does not boast, it is not proud.",
    source: "Bible",
    author: "1 Corinthians 13:4"
  }
];

let ai: GoogleGenAI | null = null;
if (process.env.API_KEY) {
  ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
}

export const fetchQuotes = async (count: number = 3): Promise<Quote[]> => {
  if (!ai) {
    console.warn("No API Key found, using fallback quotes.");
    // Return a random shuffle of fallback quotes
    return [...FALLBACK_QUOTES].sort(() => 0.5 - Math.random());
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Generate ${count} diverse and wisdom-filled quotes.
      Sources MUST be strictly from:
      1. Rashad Khalifa's authorized English translation of the Quran (God speaking).
      2. The Bible (Wisdom verses).
      3. Famous Philosophers (Stoicism, Greek, etc).

      Keep quotes between 50 and 200 characters.
      Ensure accuracy in attribution.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              text: { type: Type.STRING },
              source: { type: Type.STRING, description: "E.g., Quran, Bible, Philosophy" },
              author: { type: Type.STRING, description: "Specific author or verse reference" }
            },
            required: ["text", "source", "author"]
          }
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text);
      if (Array.isArray(data)) {
        return data as Quote[];
      }
    }
    return FALLBACK_QUOTES;
  } catch (error) {
    console.error("Error fetching quotes from Gemini:", error);
    return FALLBACK_QUOTES;
  }
};

