export const MusicPlayer: React.FC<MusicPlayerProps> = ({ isOpen, onClose, settings, setSettings }) => {
  const [activeTab, setActiveTab] = useState<'YOUTUBE' | 'SPOTIFY'>('YOUTUBE');
  const { musicConfig } = settings;

  const handlePlay = (source: MusicSource, id: string) => {
    setSettings({
      ...settings,
      musicConfig: { source, presetId: id }
    });
  };

  const handleStop = () => {
    setSettings({
      ...settings,
      musicConfig: { source: 'NONE', presetId: '' }
    });
  };

  // The actual player render (Persists even when UI is closed)
  const renderEmbed = () => {
    if (musicConfig.source === 'NONE') return null;

    if (musicConfig.source === 'YOUTUBE') {
      return (
        <div className="w-full h-full bg-black rounded-lg overflow-hidden relative group">
           {/* Cover to prevent interaction if desired, but we want users to be able to unmute if needed */}
           <iframe 
             width="100%" 
             height="100%" 
             src={`https://www.youtube.com/embed/${musicConfig.presetId}?autoplay=1&controls=1&disablekb=1&fs=0&modestbranding=1`} 
             title="YouTube music player" 
             frameBorder="0" 
             allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
             allowFullScreen
             className="opacity-80 hover:opacity-100 transition-opacity"
           ></iframe>
        </div>
      );
    }

    if (musicConfig.source === 'SPOTIFY') {
      return (
        <iframe 
          style={{ borderRadius: '12px' }} 
          src={`https://open.spotify.com/embed/playlist/${musicConfig.presetId}?utm_source=generator&theme=0`} 
          width="100%" 
          height="152" 
          frameBorder="0" 
          allowFullScreen 
          allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" 
          loading="lazy"
        ></iframe>
      );
    }
  };

  // If closed and not playing, don't render anything
  if (!isOpen && musicConfig.source === 'NONE') return null;

  return (
    <div className={`fixed bottom-6 right-6 z-50 transition-all duration-300 ${isOpen ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0 pointer-events-none'}`}>
      <div className="bg-white rounded-2xl shadow-2xl shadow-stone-300/50 w-80 border border-stone-100 overflow-hidden flex flex-col">

