          <div className={`mb-4 transition-all ${musicConfig.source === 'NONE' ? 'h-0 overflow-hidden' : 'h-auto min-h-[100px]'}`}>
             {renderEmbed()}
             <div className="mt-2 text-center">
                <button onClick={handleStop} className="text-[10px] text-red-400 font-bold hover:text-red-500 uppercase tracking-widest">
                  Stop Playback
                </button>
             </div>
          </div>

          {/* Source Tabs */}
          <div className="flex p-1 bg-stone-200/50 rounded-lg mb-4">
            <button 
              onClick={() => setActiveTab('YOUTUBE')}
              className={`flex-1 flex items-center justify-center gap-2 py-1.5 text-xs font-bold rounded-md transition-all ${activeTab === 'YOUTUBE' ? 'bg-white text-red-600 shadow-sm' : 'text-stone-500 hover:text-stone-700'}`}
            >
