            <button 
              onClick={() => setActiveTab('SPOTIFY')}
              className={`flex-1 flex items-center justify-center gap-2 py-1.5 text-xs font-bold rounded-md transition-all ${activeTab === 'SPOTIFY' ? 'bg-white text-green-600 shadow-sm' : 'text-stone-500 hover:text-stone-700'}`}
