             {PRESETS[activeTab].map((preset) => (
               <button
                 key={preset.id}
                 onClick={() => handlePlay(activeTab, preset.id)}
                 className={`w-full text-left px-3 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-between group
                   ${musicConfig.source === activeTab && musicConfig.presetId === preset.id 
