  // Initial Load
  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await loadMoreQuotes();
      setLoading(false);
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Set current quote if null and queue has items
  useEffect(() => {
    if (!currentQuote && quotesQueue.length > 0) {
      const next = quotesQueue[0];
      setCurrentQuote(next);
      setQuotesQueue(prev => prev.slice(1));
    }

    // Low buffer warning
    if (quotesQueue.length < 3 && quotesQueue.length > 0) {
      loadMoreQuotes();
    }
  }, [currentQuote, quotesQueue, loadMoreQuotes]);

  const handleQuoteComplete = (earnedXp: number, wpm: number) => {
    setXp(prev => prev + earnedXp);
    setStreak(prev => prev + 1);
    setLastWpm(wpm);
    setCurrentQuote(null); // Triggers effect to pop next quote
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  // Penalty Logic: Lose 5% of current XP
  const handleMistake = () => {
    setXp(prev => Math.floor(prev * 0.95));
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);

  return (
    <div className="min-h-screen flex flex-col bg-[#f7f7f5] text-stone-800 font-sans selection:bg-frog-200">
      {/* Top Bar Navigation */}
      <header className="w-full bg-white/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-8 py-5 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-6 md:gap-12">

          {/* Logo Area - Top Left */}
          <div className="flex flex-col items-center md:items-start flex-shrink-0">
             <h1 className="text-2xl font-black text-frog-800 tracking-tight flex items-center gap-2">
               <span className="text-3xl">🐸</span> Frog Type
             </h1>
             <p className="text-stone-400 text-xs font-medium ml-1">Cozy Typing Progression</p>
          </div>

          {/* Progress Bar Area - Right/Center */}
          <div className="w-full md:flex-grow md:max-w-3xl flex items-center gap-4">
             <ProgressBar xp={xp} />
             {/* Streak Badge in Header */}
             <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full font-mono text-xs font-bold transition-all ${streak > 0 ? 'bg-orange-50 text-orange-500' : 'bg-stone-100 text-stone-400'}`}>
                <Flame className={`w-3.5 h-3.5 ${streak > 0 ? 'fill-orange-500 animate-pulse' : ''}`} />
                <span>{streak}</span>
             </div>

             <div className="flex items-center gap-2 border-l border-stone-200 pl-4 ml-2">
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">
        <div className="w-full max-w-4xl flex items-center justify-center min-h-[50vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Hatching quotes...</p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={() => setCurrentQuote(null)}
              streak={streak}
              ghostWpm={lastWpm}
              settings={settings}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      {/* Music Player Widget (Always mounted for persistence) */}
      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
