    if (index > end) { // Strict greater to skip the space itself
        let nextEnd = text.indexOf(' ', end + 1);
        if (nextEnd === -1) nextEnd = text.length;
        if (index < nextEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Untyped
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      // Status Coloring
      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800'; // Correct
        } else {
          colorClass = 'text-red-500 bg-red-100'; // Incorrect
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-600 font-bold';
              bgClass = 'bg-frog-50';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} className="relative inline-block">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}
            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  return (
    <div 
      className="relative w-full max-w-3xl mx-auto min-h-[320px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-[2px] cursor-pointer rounded-[2.5rem] border-2 border-dashed border-frog-200/50 hover:border-frog-300 transition-all"
        >
          <div className="text-center animate-bounce text-frog-500">
            <Play className="w-8 h-8 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-sm tracking-wide uppercase font-sans">Click or Type to Start</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-10 md:p-16 bg-[#fffdf7] rounded-[2.5rem] transition-all duration-300 border border-[#e6e1d5]
        ${!isFocused ? 'blur-[1px] opacity-60' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-100 shadow-[0_0_20px_rgba(239,68,68,0.15)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-100 bg-frog-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : 'shadow-xl shadow-stone-200/60'}
      `}>

        {/* Decorative Quote Icon */}
        <div className="absolute top-8 left-8 text-stone-100 select-none pointer-events-none">
          <QuoteIcon className="w-20 h-20 opacity-40 fill-stone-100" />
        </div>

        {/* Source Header */}
        <div className="absolute top-8 left-0 right-0 px-16 flex justify-between text-[11px] font-bold text-stone-400/80 uppercase tracking-[0.2em] select-none font-sans">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3 h-3"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadEnabled && <span className="text-frog-300 flex items-center gap-1"><EyeOff className="w-3 h-3"/> Read Ahead</span>}
          </div>
          <span>{quote.author}</span>
        </div>

        {/* Text Display */}
        <div 
          className="font-serif text-3xl md:text-4xl leading-loose tracking-wide break-words whitespace-pre-wrap mb-10 mt-8 relative z-10 outline-none select-none text-stone-300"
          onClick={handleFocus}
        >
          {renderText()}
        </div>

        {/* Hidden Input */}
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => setIsFocused(true)}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        {/* Status Bar */}
        <div className="absolute bottom-8 left-0 right-0 px-16 flex justify-between items-end select-none">
           <div className="flex items-center gap-8 text-stone-400 font-mono text-xs">
             <div className="flex flex-col">
                <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-lg text-stone-600 font-sans">{wpm} <span className="text-[10px] font-normal text-stone-400">WPM</span></span>
             </div>
             {status === GameStatus.COMPLETED && (
                 <div className="flex flex-col animate-pulse text-frog-600">
                    <span className="text-[9px] uppercase font-bold text-frog-400 mb-0.5 tracking-wider">XP Earned</span>
                    <span className="font-bold text-lg font-sans">+{calculateXP(wpm, quote.text.length)}</span>
                 </div>
             )}
             {/* Streak Indicator in-game */}
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-lg flex items-center gap-1 font-sans">
                        <Flame className={`w-3.5 h-3.5 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-5 py-2 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-xs tracking-wide uppercase"
                >
                  <RotateCcw className="w-3.5 h-3.5" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-6 py-2.5 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200/50 font-bold text-xs tracking-wide uppercase transform hover:-translate-y-0.5"
                >
                  Next Quote <Award className="w-3.5 h-3.5" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-6 h-4 text-stone-400 text-[11px] font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? <span className="text-red-400">100% Accuracy Required. Streak Reset.</span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-500">Perfect! Streak +1</span> :
         isFocused ? "Type the quote above exactly." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Quote, GameStatus, Settings } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Quote as QuoteIcon } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number) => void;
  onFail: () => void;
  onMistake: () => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings 
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED) {
        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status]);

  const handleFocus = () => {
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        // Update WPM
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        // Update Ghost
        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            // Ghost speed: chars = WPM * 5 * mins
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50); // 20fps update for smooth ghost
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;
    const prevLen = input.length;

    // Start timer on first char
    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    // Mistake Penalty Check
    // We only check characters that are newly added.
    if (val.length > prevLen) {
      for (let i = prevLen; i < val.length; i++) {
        if (i < quote.text.length) {
          if (val[i] !== quote.text[i]) {
            onMistake();
          }
        }
      }
    }

    setInput(val);

    // Check completion
    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const handleRetry = () => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleNext = () => {
    onComplete(calculateXP(wpm, quote.text.length), wpm);
  };

  // Helper for Read Ahead logic
  const getReadAheadState = (index: number) => {
    if (!settings.readAheadEnabled) return { isHidden: false, isHighlighted: false };

    // Find current word boundaries
    // "Current Word" is the one the caret is currently in or just finished
    const text = quote.text;
    const caret = input.length;

    // Find start of current word (go back from caret until space)
    let start = text.lastIndexOf(' ', caret - 1);
    start = start === -1 ? 0 : start + 1;

    // Find end of current word (go forward from caret until space)
    let end = text.indexOf(' ', caret);
    if (end === -1) end = text.length;

    // Check if index is in current word
    if (index >= start && index < end) {
        return { isHidden: true, isHighlighted: false };
    }

    // Check if index is in next word
    // Next word starts after `end` space
    if (index > end) { // Strict greater to skip the space itself
        let nextEnd = text.indexOf(' ', end + 1);
        if (nextEnd === -1) nextEnd = text.length;
        if (index < nextEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Untyped
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      // Status Coloring
      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800'; // Correct
        } else {
          colorClass = 'text-red-500 bg-red-100'; // Incorrect
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-600 font-bold';
              bgClass = 'bg-frog-50';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}
            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  return (
    <div 
      className="relative w-full max-w-3xl mx-auto min-h-[320px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-[2px] cursor-pointer rounded-[2.5rem] border-2 border-dashed border-frog-200/50 hover:border-frog-300 transition-all"
        >
          <div className="text-center animate-bounce text-frog-500">
            <Play className="w-8 h-8 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-sm tracking-wide uppercase font-sans">Click or Type to Start</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-10 md:p-16 bg-[#fffdf7] rounded-[2.5rem] transition-all duration-300 border border-[#e6e1d5]
        ${!isFocused ? 'blur-[1px] opacity-60' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-100 shadow-[0_0_20px_rgba(239,68,68,0.15)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-100 bg-frog-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : 'shadow-xl shadow-stone-200/60'}
      `}>

        {/* Decorative Quote Icon */}
        <div className="absolute top-8 left-8 text-stone-100 select-none pointer-events-none">
          <QuoteIcon className="w-20 h-20 opacity-40 fill-stone-100" />
        </div>

        {/* Source Header */}
        <div className="absolute top-8 left-0 right-0 px-16 flex justify-between text-[11px] font-bold text-stone-400/80 uppercase tracking-[0.2em] select-none font-sans">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3 h-3"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadEnabled && <span className="text-frog-300 flex items-center gap-1"><EyeOff className="w-3 h-3"/> Read Ahead</span>}
          </div>
          <span>{quote.author}</span>
        </div>

        {/* Text Display */}
        <div 
          className="font-serif text-3xl md:text-4xl leading-relaxed tracking-wide break-words whitespace-pre-wrap mb-10 mt-8 relative z-10 outline-none select-none text-stone-300"
          onClick={handleFocus}
        >
          {renderText()}
        </div>

        {/* Hidden Input */}
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => setIsFocused(true)}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        {/* Status Bar */}
        <div className="absolute bottom-8 left-0 right-0 px-16 flex justify-between items-end select-none">
           <div className="flex items-center gap-8 text-stone-400 font-mono text-xs">
             <div className="flex flex-col">
                <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-lg text-stone-600 font-sans">{wpm} <span className="text-[10px] font-normal text-stone-400">WPM</span></span>
             </div>
             {status === GameStatus.COMPLETED && (
                 <div className="flex flex-col animate-pulse text-frog-600">
                    <span className="text-[9px] uppercase font-bold text-frog-400 mb-0.5 tracking-wider">XP Earned</span>
                    <span className="font-bold text-lg font-sans">+{calculateXP(wpm, quote.text.length)}</span>
                 </div>
             )}
             {/* Streak Indicator in-game */}
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-lg flex items-center gap-1 font-sans">
                        <Flame className={`w-3.5 h-3.5 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-5 py-2 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-xs tracking-wide uppercase"
                >
                  <RotateCcw className="w-3.5 h-3.5" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-6 py-2.5 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200/50 font-bold text-xs tracking-wide uppercase transform hover:-translate-y-0.5"
                >
                  Next Quote <Award className="w-3.5 h-3.5" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-6 h-4 text-stone-400 text-[11px] font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? <span className="text-red-400">100% Accuracy Required. Streak Reset.</span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-500">Perfect! Streak +1</span> :
         isFocused ? "Type the quote above exactly." : ""}
      </div>
    </div>
  );
};

