import React, { useState, useEffect, useCallback } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode } from './types';
import { fetchQuotes } from './services/geminiService';
import { Loader2, Settings as SettingsIcon, Flame, Music, CircleHelp, Skull, BookOpen, Eraser } from 'lucide-react';

const App: React.FC = () => {
  const [xp, setXp] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_xp');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};
    return { 
      ghostEnabled: false, 
      readAheadEnabled: false, 
      musicConfig: { source: 'NONE', presetId: '' },
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>('QUOTES');
  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);
  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [loading, setLoading] = useState(false); // Changed default to false to handle initial load explicitly
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);

  // Persistence
  useEffect(() => { localStorage.setItem('frogType_xp', xp.toString()); }, [xp]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);

  // Generate a quote from mistakes
  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;

    // Shuffle and pick up to 10 words
    const shuffled = [...mistakePool].sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 10);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    try {
      const newQuotes = await fetchQuotes(5);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    }
  }, []);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await loadMoreQuotes();
      setLoading(false);
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Quote Management Logic
  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        // Fallback if cleared
        setGameMode('QUOTES'); 
      }
    } else {
      // Normal or Hardcore Mode
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      // Low buffer warning
      if (quotesQueue.length < 3 && quotesQueue.length > 0) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const handleQuoteComplete = (earnedXp: number, wpm: number) => {
    let finalXp = earnedXp;

    // Hardcore Mode Reward: 10x XP
    if (gameMode === 'HARDCORE') {
      finalXp = earnedXp * 10;
    }

    // Fix Mistake Mode: Remove words from pool
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = currentQuote.text.split(' ');
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    setXp(prev => prev + finalXp);
    setStreak(prev => prev + 1);
    setLastWpm(wpm);
    setCurrentQuote(null); // Triggers effect to pop next quote
  };

  const handleQuoteFail = () => {
    setStreak(0);
    // Hardcore mode resets are handled visually in TypingArea, 
    // but the streak reset happens here.
  };

  const handleMistake = (word?: string) => {
    // 1. Penalty Logic: Lose 5% of current XP (Standard in Quotes/Hardcore)
    // Note: Hardcore fails instantly, but we still apply penalty on that failure frame
    setXp(prev => Math.floor(prev * 0.95));

    // 2. Save Mistake Word
    if (word && word.length > 1) {
       // Avoid duplicates
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    setGameMode(mode);
    setCurrentQuote(null); // Reset current quote to force fetch new type
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f7f7f5] text-stone-800 font-sans selection:bg-frog-200">
      {/* Top Bar Navigation */}
      <header className="w-full bg-white/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-8 py-5 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-6 md:gap-12">

          {/* Logo Area - Top Left */}
          <div className="flex flex-col items-center md:items-start flex-shrink-0">
             <h1 className="text-2xl font-black text-frog-800 tracking-tight flex items-center gap-2">
               <span className="text-3xl">🐸</span> Frog Type
             </h1>
             <p className="text-stone-400 text-xs font-medium ml-1">Cozy Typing Progression</p>
          </div>

          {/* Progress Bar Area - Right/Center */}
          <div className="w-full md:flex-grow md:max-w-3xl flex items-center gap-4">
             <ProgressBar xp={xp} />
             {/* Streak Badge in Header */}
             <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full font-mono text-xs font-bold transition-all ${streak > 0 ? 'bg-orange-50 text-orange-500' : 'bg-stone-100 text-stone-400'}`}>
                <Flame className={`w-3.5 h-3.5 ${streak > 0 ? 'fill-orange-500 animate-pulse' : ''}`} />
                <span>{streak}</span>
             </div>

             <div className="flex items-center gap-2 border-l border-stone-200 pl-4 ml-2">
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">

        {/* Game Mode Selector */}
        <div className="mb-8 flex gap-2 p-1 bg-white rounded-xl shadow-sm border border-stone-200">
           <button 
              onClick={() => switchMode('QUOTES')}
              className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${gameMode === 'QUOTES' ? 'bg-frog-500 text-white shadow-md' : 'text-stone-500 hover:bg-stone-50'}`}
           >
              <BookOpen className="w-4 h-4" /> Quotes
           </button>
           <button 
              onClick={() => switchMode('HARDCORE')}
              className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${gameMode === 'HARDCORE' ? 'bg-stone-800 text-white shadow-md' : 'text-stone-500 hover:bg-stone-50'}`}
           >
              <Skull className="w-4 h-4" /> Hardcore
           </button>
           <button 
              onClick={() => switchMode('FIX_MISTAKE')}
              disabled={mistakePool.length === 0}
              className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all 
                ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-md' : 'text-stone-500 hover:bg-stone-50'}
                ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
              `}
              title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
           >
              <Eraser className="w-4 h-4" /> Fix Mistakes
              {mistakePool.length > 0 && <span className="text-[10px] bg-white/20 px-1.5 rounded-full">{mistakePool.length}</span>}
           </button>
        </div>

        <div className="w-full max-w-4xl flex items-center justify-center min-h-[50vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Hatching quotes...</p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={() => setCurrentQuote(null)}
              streak={streak}
              ghostWpm={lastWpm}
              settings={settings}
              gameMode={gameMode}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      {/* Music Player Widget (Always mounted for persistence) */}
      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Quote, GameStatus, Settings, GameMode } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Quote as QuoteIcon, Skull, Eraser } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number) => void;
  onFail: () => void;
  onMistake: (word?: string) => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED) {
        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status]);

  const handleFocus = () => {
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        // Update WPM
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        // Update Ghost
        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            // Ghost speed: chars = WPM * 5 * mins
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50); // 20fps update for smooth ghost
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const getWordAt = (index: number, text: string) => {
    const start = text.lastIndexOf(' ', index) + 1;
    let end = text.indexOf(' ', index);
    if (end === -1) end = text.length;
    return text.slice(start, end).replace(/[.,;!?]/g, ''); // strip punctuation for cleaner saving
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;
    const prevLen = input.length;

    // Start timer on first char
    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    // --- Hardcore Mode Instant Fail Check ---
    if (gameMode === 'HARDCORE') {
       if (val.length > 0) {
         // Check if the current input matches the start of the quote
         if (!quote.text.startsWith(val)) {
            setStatus(GameStatus.FAILED);
            onFail();
            // In Hardcore, we penalize and fail immediately
            onMistake(); 
            // Also capture the word that caused the fail
            const word = getWordAt(val.length - 1, quote.text);
            onMistake(word);
            return;
         }
       }
    }

    // --- Mistake Detection (All Modes) ---
    // We only check characters that are newly added.
    if (val.length > prevLen) {
      for (let i = prevLen; i < val.length; i++) {
        if (i < quote.text.length) {
          if (val[i] !== quote.text[i]) {
            // Find the word associated with this mistake
            const word = getWordAt(i, quote.text);
            onMistake(word);
          }
        }
      }
    }

    setInput(val);

    // Check completion
    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const handleRetry = () => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleNext = () => {
    onComplete(calculateXP(wpm, quote.text.length), wpm);
  };

  // Helper for Read Ahead logic
  const getReadAheadState = (index: number) => {
    if (!settings.readAheadEnabled) return { isHidden: false, isHighlighted: false };

    // Find current word boundaries
    // "Current Word" is the one the caret is currently in or just finished
    const text = quote.text;
    const caret = input.length;

    // Find start of current word (go back from caret until space)
    let start = text.lastIndexOf(' ', caret - 1);
    start = start === -1 ? 0 : start + 1;

    // Find end of current word (go forward from caret until space)
    let end = text.indexOf(' ', caret);
    if (end === -1) end = text.length;

    // Check if index is in current word
    if (index >= start && index < end) {
        return { isHidden: true, isHighlighted: false };
    }

    // Check if index is in next word
    // Next word starts after `end` space
    if (index > end) { // Strict greater to skip the space itself
        let nextEnd = text.indexOf(' ', end + 1);
        if (nextEnd === -1) nextEnd = text.length;
        if (index < nextEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Untyped
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      // Status Coloring
      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800'; // Correct
        } else {
          colorClass = 'text-red-500 bg-red-100'; // Incorrect
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-600 font-bold';
              bgClass = 'bg-frog-50';
          }
      }

      // Visual Aid for Fix Mistake Mode
      if (gameMode === 'FIX_MISTAKE') {
          // Highlight untyped words in red in this mode
          if (index >= input.length) {
              colorClass = 'text-red-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}
            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (gameMode === 'HARDCORE') {
        return 'bg-stone-900 border-stone-800 text-stone-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'FIX_MISTAKE') {
        return 'bg-red-50 border-red-100';
    }
    return 'bg-[#fffdf7] border-[#e6e1d5]';
  };

  const getTextColor = () => {
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  return (
    <div 
      className="relative w-full max-w-3xl mx-auto min-h-[320px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-[2px] cursor-pointer rounded-[2.5rem] border-2 border-dashed border-frog-200/50 hover:border-frog-300 transition-all"
        >
          <div className="text-center animate-bounce text-frog-500">
            <Play className="w-8 h-8 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-sm tracking-wide uppercase font-sans">Click or Type to Start</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-10 md:p-16 rounded-[2.5rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${!isFocused ? 'blur-[1px] opacity-60' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-100 bg-frog-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {/* Decorative Icons */}
        <div className="absolute top-8 left-8 select-none pointer-events-none">
           {gameMode === 'QUOTES' && <QuoteIcon className="w-20 h-20 opacity-40 fill-stone-100" />}
           {gameMode === 'HARDCORE' && <Skull className="w-20 h-20 opacity-10 text-stone-600" />}
           {gameMode === 'FIX_MISTAKE' && <Eraser className="w-20 h-20 opacity-20 text-red-200" />}
        </div>

        {/* Source Header */}
        <div className="absolute top-8 left-0 right-0 px-16 flex justify-between text-[11px] font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans">
          <div className="flex gap-4">
             <span>{quote.source}</span>
             {settings.ghostEnabled && <span className="text-purple-300 flex items-center gap-1"><Ghost className="w-3 h-3"/> {ghostWpm > 0 ? `${ghostWpm} WPM` : 'Ready'}</span>}
             {settings.readAheadEnabled && <span className="text-frog-300 flex items-center gap-1"><EyeOff className="w-3 h-3"/> Read Ahead</span>}
          </div>
          <span>{quote.author}</span>
        </div>

        {/* Text Display */}
        <div 
          className={`font-serif text-3xl md:text-4xl leading-relaxed tracking-wide break-words whitespace-pre-wrap mb-10 mt-8 relative z-10 outline-none select-none ${getTextColor()}`}
          onClick={handleFocus}
        >
          {renderText()}
        </div>

        {/* Hidden Input */}
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => setIsFocused(true)}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        {/* Status Bar */}
        <div className="absolute bottom-8 left-0 right-0 px-16 flex justify-between items-end select-none">
           <div className="flex items-center gap-8 text-stone-400 font-mono text-xs">
             <div className="flex flex-col">
                <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Speed</span>
                <span className="font-bold text-lg opacity-80 font-sans">{wpm} <span className="text-[10px] font-normal opacity-50">WPM</span></span>
             </div>
             {status === GameStatus.COMPLETED && (
                 <div className="flex flex-col animate-pulse text-frog-600">
                    <span className="text-[9px] uppercase font-bold text-frog-400 mb-0.5 tracking-wider">XP Earned</span>
                    <span className="font-bold text-lg font-sans">+{calculateXP(wpm, quote.text.length) * (gameMode === 'HARDCORE' ? 10 : 1)}</span>
                 </div>
             )}
             {/* Streak Indicator in-game */}
             {streak > 0 && (
                <div className={`flex flex-col ${streak > 4 ? 'text-orange-500' : 'text-stone-400'}`}>
                    <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5 tracking-wider">Streak</span>
                    <span className="font-bold text-lg flex items-center gap-1 font-sans">
                        <Flame className={`w-3.5 h-3.5 ${streak > 4 ? 'fill-orange-500' : ''}`} /> {streak}
                    </span>
                </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-5 py-2 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-xs tracking-wide uppercase"
                >
                  <RotateCcw className="w-3.5 h-3.5" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-6 py-2.5 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200/50 font-bold text-xs tracking-wide uppercase transform hover:-translate-y-0.5"
                >
                  Next Quote <Award className="w-3.5 h-3.5" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-6 h-4 text-stone-400 text-[11px] font-medium tracking-wide transition-opacity duration-500 font-sans">
        {status === GameStatus.FAILED ? 
            <span className="text-red-400">
                {gameMode === 'HARDCORE' ? 'HARDCORE FAIL. 100% Accuracy Required.' : '100% Accuracy Required. Streak Reset.'}
            </span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-500">Perfect! Streak +1</span> :
         isFocused ? (gameMode === 'HARDCORE' ? "HARDCORE MODE: One mistake = Instant Fail." : "Type the quote above exactly.") : ""}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useCallback } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode } from './types';
import { fetchQuotes } from './services/geminiService';
import { Loader2, Settings as SettingsIcon, Flame, Music, CircleHelp, Skull, BookOpen, Eraser } from 'lucide-react';

const App: React.FC = () => {
  const [xp, setXp] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_xp');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};
    return { 
      ghostEnabled: false, 
      readAheadEnabled: false, 
      musicConfig: { source: 'NONE', presetId: '' },
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>('QUOTES');
  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);
  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [loading, setLoading] = useState(false); // Changed default to false to handle initial load explicitly
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);

  // Persistence
  useEffect(() => { localStorage.setItem('frogType_xp', xp.toString()); }, [xp]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);

  // Generate a quote from mistakes
  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;

    // Shuffle and pick up to 10 words
    const shuffled = [...mistakePool].sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 10);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    try {
      const newQuotes = await fetchQuotes(5);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    }
  }, []);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await loadMoreQuotes();
      setLoading(false);
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Quote Management Logic
  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        // Fallback if cleared
        setGameMode('QUOTES'); 
      }
    } else {
      // Normal or Hardcore Mode
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      // Low buffer warning
      if (quotesQueue.length < 3 && quotesQueue.length > 0) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const handleQuoteComplete = (earnedXp: number, wpm: number) => {
    let finalXp = earnedXp;

    // Hardcore Mode Reward: 10x XP
    if (gameMode === 'HARDCORE') {
      finalXp = earnedXp * 10;
    }

    // Fix Mistake Mode: Remove words from pool
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      const wordsFixed = currentQuote.text.split(' ');
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    setXp(prev => prev + finalXp);
    setStreak(prev => prev + 1);
    setLastWpm(wpm);
    setCurrentQuote(null); // Triggers effect to pop next quote
  };

  const handleQuoteFail = () => {
    setStreak(0);
    // Hardcore mode resets are handled visually in TypingArea, 
    // but the streak reset happens here.
  };

  const handleMistake = (word?: string) => {
    // 1. Penalty Logic: Lose 5% of current XP (Standard in Quotes/Hardcore)
    // Note: Hardcore fails instantly, but we still apply penalty on that failure frame
    setXp(prev => Math.floor(prev * 0.95));

    // 2. Save Mistake Word
    if (word && word.length > 1) {
       // Avoid duplicates
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    setGameMode(mode);
    setCurrentQuote(null); // Reset current quote to force fetch new type
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f7f7f5] text-stone-800 font-sans selection:bg-frog-200">
      {/* Top Bar Navigation */}
      <header className="w-full bg-white/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-[1400px] mx-auto flex flex-col xl:flex-row items-center justify-between gap-4 xl:gap-8">

          {/* Group 1: Logo & Modes */}
          <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8 w-full xl:w-auto">
            {/* Logo */}
            <div className="flex flex-col items-center md:items-start flex-shrink-0">
              <h1 className="text-xl font-black text-frog-800 tracking-tight flex items-center gap-2">
                <span className="text-2xl">🐸</span> Frog Type
              </h1>
            </div>

            {/* Game Mode Selector (Moved to Header) */}
            <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50">
              <button 
                  onClick={() => switchMode('QUOTES')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all ${gameMode === 'QUOTES' ? 'bg-white text-frog-600 shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <BookOpen className="w-3.5 h-3.5" /> Quotes
              </button>
              <button 
                  onClick={() => switchMode('HARDCORE')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all ${gameMode === 'HARDCORE' ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <Skull className="w-3.5 h-3.5" /> Hardcore
              </button>
              <button 
                  onClick={() => switchMode('FIX_MISTAKE')}
                  disabled={mistakePool.length === 0}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all 
                    ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                    ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                  `}
                  title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
              >
                  <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
              </button>
            </div>
          </div>

          {/* Group 2: Progress & Tools */}
          <div className="w-full xl:w-auto xl:flex-grow xl:max-w-2xl flex items-center gap-4 justify-end">
             <ProgressBar xp={xp} />
             {/* Streak Badge in Header */}
             <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full font-mono text-xs font-bold transition-all shrink-0 ${streak > 0 ? 'bg-orange-50 text-orange-500' : 'bg-stone-100 text-stone-400'}`}>
                <Flame className={`w-3.5 h-3.5 ${streak > 0 ? 'fill-orange-500 animate-pulse' : ''}`} />
                <span>{streak}</span>
             </div>

             <div className="flex items-center gap-1.5 border-l border-stone-200 pl-4 ml-2 shrink-0">
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">

        <div className="w-full flex items-center justify-center min-h-[60vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Hatching quotes...</p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={() => setCurrentQuote(null)}
              streak={streak}
              ghostWpm={lastWpm}
              settings={settings}
              gameMode={gameMode}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      {/* Music Player Widget (Always mounted for persistence) */}
      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Quote, GameStatus, Settings, GameMode } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { Play, RotateCcw, Award, Flame, Ghost, EyeOff, Quote as QuoteIcon, Skull, Eraser } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number) => void;
  onFail: () => void;
  onMistake: (word?: string) => void;
  onRequestNewQuote: () => void;
  streak: number;
  ghostWpm: number;
  settings: Settings;
  gameMode: GameMode;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onMistake,
  onRequestNewQuote,
  streak,
  ghostWpm,
  settings,
  gameMode
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED) {
        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status]);

  const handleFocus = () => {
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        // Update WPM
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        // Update Ghost
        if (settings.ghostEnabled && ghostWpm > 0 && startTime) {
            const now = Date.now();
            const elapsedMins = (now - startTime) / 60000;
            // Ghost speed: chars = WPM * 5 * mins
            const projectedChars = (ghostWpm * 5) * elapsedMins;
            setGhostIndex(projectedChars);
        }
      }, 50); // 20fps update for smooth ghost
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostEnabled, ghostWpm, startTime]);

  const getWordAt = (index: number, text: string) => {
    const start = text.lastIndexOf(' ', index) + 1;
    let end = text.indexOf(' ', index);
    if (end === -1) end = text.length;
    return text.slice(start, end).replace(/[.,;!?]/g, ''); // strip punctuation for cleaner saving
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;
    const prevLen = input.length;

    // Start timer on first char
    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    // --- Hardcore Mode Instant Fail Check ---
    if (gameMode === 'HARDCORE') {
       if (val.length > 0) {
         // Check if the current input matches the start of the quote
         if (!quote.text.startsWith(val)) {
            setStatus(GameStatus.FAILED);
            onFail();
            // In Hardcore, we penalize and fail immediately
            onMistake(); 
            // Also capture the word that caused the fail
            const word = getWordAt(val.length - 1, quote.text);
            onMistake(word);
            return;
         }
       }
    }

    // --- Mistake Detection (All Modes) ---
    // We only check characters that are newly added.
    if (val.length > prevLen) {
      for (let i = prevLen; i < val.length; i++) {
        if (i < quote.text.length) {
          if (val[i] !== quote.text[i]) {
            // Find the word associated with this mistake
            const word = getWordAt(i, quote.text);
            onMistake(word);
          }
        }
      }
    }

    setInput(val);

    // Check completion
    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const handleRetry = () => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleNext = () => {
    onComplete(calculateXP(wpm, quote.text.length), wpm);
  };

  // Helper for Read Ahead logic
  const getReadAheadState = (index: number) => {
    if (!settings.readAheadEnabled) return { isHidden: false, isHighlighted: false };

    // Find current word boundaries
    // "Current Word" is the one the caret is currently in or just finished
    const text = quote.text;
    const caret = input.length;

    // Find start of current word (go back from caret until space)
    let start = text.lastIndexOf(' ', caret - 1);
    start = start === -1 ? 0 : start + 1;

    // Find end of current word (go forward from caret until space)
    let end = text.indexOf(' ', caret);
    if (end === -1) end = text.length;

    // Check if index is in current word
    if (index >= start && index < end) {
        return { isHidden: true, isHighlighted: false };
    }

    // Check if index is in next word
    // Next word starts after `end` space
    if (index > end) { // Strict greater to skip the space itself
        let nextEnd = text.indexOf(' ', end + 1);
        if (nextEnd === -1) nextEnd = text.length;
        if (index < nextEnd) {
             return { isHidden: false, isHighlighted: true };
        }
    }

    return { isHidden: false, isHighlighted: false };
  };

  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Untyped
      let bgClass = '';

      const { isHidden, isHighlighted } = getReadAheadState(index);

      // Status Coloring
      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800'; // Correct
        } else {
          colorClass = 'text-red-500 bg-red-100'; // Incorrect
        }
      } else {
          if (isHighlighted) {
              colorClass = 'text-frog-600 font-bold';
              bgClass = 'bg-frog-50';
          }
      }

      // Visual Aid for Fix Mistake Mode
      if (gameMode === 'FIX_MISTAKE') {
          // Highlight untyped words in red in this mode
          if (index >= input.length) {
              colorClass = 'text-red-300';
          }
      }

      const isGhostHere = settings.ghostEnabled && Math.floor(ghostIndex) === index;

      return (
        <span key={index} className="relative">
            {isGhostHere && (
                <span className="absolute -left-[2px] top-0 bottom-0 w-[2px] bg-purple-400/50 z-20 animate-pulse">
                     <span className="absolute -top-4 -left-2 text-[10px] text-purple-400 opacity-70">👻</span>
                </span>
            )}
            <span 
                className={`
                    ${colorClass} ${bgClass} transition-colors duration-100
                    ${isHidden ? 'text-transparent selection:text-transparent' : ''}
                    ${isHidden && index < input.length && input[index] !== char ? '!text-red-500 !bg-red-100' : ''} 
                `}
            >
                {char}
            </span>
        </span>
      );
    });
  };

  const getContainerStyle = () => {
    if (gameMode === 'HARDCORE') {
        return 'bg-stone-900 border-stone-800 text-stone-400 shadow-[0_0_40px_rgba(0,0,0,0.2)]';
    }
    if (gameMode === 'FIX_MISTAKE') {
        return 'bg-red-50 border-red-100';
    }
    return 'bg-[#fffdf7] border-[#e6e1d5]';
  };

  const getTextColor = () => {
     if (gameMode === 'HARDCORE') return 'text-stone-400';
     return 'text-stone-300';
  };

  return (
    <div 
      className="relative w-full max-w-6xl mx-auto min-h-[400px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-stone-900/5 backdrop-blur-[2px] cursor-pointer rounded-[3rem] border-2 border-dashed border-frog-200/50 hover:border-frog-300 transition-all"
        >
          <div className="text-center animate-bounce text-frog-500">
            <Play className="w-10 h-10 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-base tracking-wide uppercase font-sans">Click or Type to Start</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-12 md:p-20 rounded-[3rem] transition-all duration-300 border
        ${getContainerStyle()}
        ${!isFocused ? 'blur-[1px] opacity-60' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-100 bg-frog-50/20' : ''}
        ${streak > 2 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(251,146,60,0.15)] ring-1 ring-orange-100' : ''}
      `}>

        {/* Decorative Icons */}
        <div className="absolute top-10 left-10 select-none pointer-events-none">
           {gameMode === 'QUOTES' && <QuoteIcon className="w-24 h-24 opacity-40 fill-stone-100" />}
           {gameMode === 'HARDCORE' && <Skull className="w-24 h-24 opacity-10 text-stone-600" />}
           {gameMode === 'FIX_MISTAKE' && <Eraser className="w-24 h-24 opacity-20 text-red-200" />}
        </div>

        {/* Source Header */}
        <div className="absolute top-10 left-0 right-0 px-20 flex justify-between text-xs font-bold opacity-80 uppercase tracking-[0.2em] select-none font-sans">
          <div className="flex gap-4">
             <span>{quote.source}</span>
