           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-6 py-2.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-sm tracking-wide uppercase"
                >
