                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-8 py-3 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200/50 font-bold text-sm tracking-wide uppercase transform hover:-translate-y-0.5"
