  FAILED = 'FAILED', // Typed but mistakes were present at the end
}

import { Level } from '../types';

export const LEVELS: Level[] = [
  // Egg (Stone/Grey)
  { name: 'Egg III', minXP: 0, color: 'stone', shade: '700' }, // Darker
  { name: 'Egg II', minXP: 700, color: 'stone', shade: '600' },
