  { name: 'Polliwog II', minXP: 8900, color: 'emerald', shade: '600' },
  { name: 'Polliwog I', minXP: 11200, color: 'emerald', shade: '500' },

  // Froglet (Cyan/Sky)
  { name: 'Froglet III', minXP: 13600, color: 'cyan', shade: '700' },
  { name: 'Froglet II', minXP: 17000, color: 'cyan', shade: '600' },
  { name: 'Froglet I', minXP: 20500, color: 'cyan', shade: '500' },

  // Hopper (Blue)
  { name: 'Hopper III', minXP: 24000, color: 'blue', shade: '700' },
  { name: 'Hopper II', minXP: 33000, color: 'blue', shade: '600' },
  { name: 'Hopper I', minXP: 42000, color: 'blue', shade: '500' },

  // Tree Frog (Violet/Purple)
  { name: 'Tree Frog III', minXP: 50000, color: 'violet', shade: '700' },
  { name: 'Tree Frog II', minXP: 67000, color: 'violet', shade: '600' },
  { name: 'Tree Frog I', minXP: 83000, color: 'violet', shade: '500' },

  // Bullfrog (Orange) - Legendary
  { name: 'Bullfrog', minXP: 100000, color: 'orange', shade: '500' },

  // Frog Sage (Red) - Mythic
  { name: 'Frog Sage', minXP: 150000, color: 'red', shade: '600' }, 
];

export const getCurrentLevel = (xp: number): Level => {
  // Find the highest level where xp >= minXP
  for (let i = LEVELS.length - 1; i >= 0; i--) {
    if (xp >= LEVELS[i].minXP) {
      return LEVELS[i];
    }
  }
  return LEVELS[0];
};

export const getNextLevel = (currentLevel: Level): Level | null => {
  const index = LEVELS.indexOf(currentLevel);
  if (index >= 0 && index < LEVELS.length - 1) {
    return LEVELS[index + 1];
  }
  return null; // Max level reached
};

export const calculateXP = (wpm: number, length: number): number => {
  // Logic: XP = Typing speed * number of letters typed
  return Math.floor(wpm * length);
};

